css:
/* Editorial reading theme: adaptive palette, typography, card rhythm, print. */
:root { --bg: #f2ede2; --surface: #fffdf7; --border: #c4bba8; --text: #252b28; --text-medium: #424b43; --text-muted: #586057; --text-ghost: #62695f; --accent-strong: #22604c; --radius: 8px; --line-height: 1.75; }
:root.dark { --bg: #202722; --surface: #29332c; --border: #647264; --text: #faf3df; --text-medium: #e4dcc9; --text-muted: #c9c7b3; --text-ghost: #b8baa5; --accent-strong: #a7e4bb; }
.header { border-bottom: 3px double var(--border); background: var(--surface); }
#brandBtn { letter-spacing: -.035em; font-family: Georgia, serif; }
.card-tile { border: 1px solid var(--border); border-radius: 8px; box-shadow: 0 3px 0 var(--border); padding: clamp(12px, 2vw, 22px); transition: transform 140ms ease; }
.card-tile:hover { transform: translateY(-2px); }
.card-content { line-height: 1.75; }
.card-content p { max-width: 72ch; }
.card-tag { background: var(--bg); color: var(--accent-strong); border: 1px solid var(--border); border-radius: 999px; padding: 3px 8px; }
.menu-panel { border-left: 3px double var(--border); }
.search-input-wrapper { border-radius: 999px; background: var(--surface); }
:root:not(.high-contrast) :focus-visible { outline: 3px solid var(--accent-strong); outline-offset: 4px; }
@media (max-width: 540px) { .card-tile { padding: 12px; box-shadow: none; } #brandBtn { font-size: clamp(1.3rem, 7vw, 2rem); } }
@media (prefers-reduced-motion: reduce) { .card-tile { transition: none; } .card-tile:hover { transform: none; } }
@media (forced-colors: active) { .card-tile, .card-tag { border: 1px solid CanvasText; box-shadow: none; } }
@media print { :root, :root.dark { --bg: white; --surface: white; --text: black; --text-muted: #333; --border: #888; } .header, .menu-panel { display: none; } .card-tile { break-inside: avoid; box-shadow: none; transform: none; } }

/* Shared finishing rules keep links, placeholders and selected controls on
   the same tested palette. Existing high-contrast rules retain control. */
:root:not(.high-contrast) a { color: var(--accent-strong); text-underline-offset: .16em; }
:root:not(.high-contrast) a:hover { color: var(--text); }
:root:not(.high-contrast) .breadcrumb.current { color: var(--text-muted); }
:root:not(.high-contrast) input::placeholder, :root:not(.high-contrast) textarea::placeholder { color: var(--text-muted); opacity: 1; }
:root:not(.high-contrast) .density-btn.active { background: var(--text); color: var(--bg); border-color: var(--text); }
:root:not(.high-contrast) .density-btn:hover { outline: 1px solid var(--text); }
:root:not(.high-contrast) .save-status.saved { color: var(--accent-strong); background: var(--surface); border-color: var(--accent-strong); }
@media (prefers-reduced-motion: reduce) { .save-status, .density-btn { transition: none; animation: none; } }
